// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAgentOverviews Live AgentOverviewList data and recorded performance statistics
	// (GET /agent-overviews)
	ListAgentOverviews(ctx context.Context, request ListAgentOverviewsRequestObject) (ListAgentOverviewsResponseObject, error)
	// CreateAgent Create an agent with a default definition
	// (POST /agents)
	CreateAgent(ctx context.Context, request CreateAgentRequestObject) (CreateAgentResponseObject, error)
	// GetAgent An agent with its current definition, history and project overrides
	// (GET /agents/{handle})
	GetAgent(ctx context.Context, request GetAgentRequestObject) (GetAgentResponseObject, error)
	// SaveAgentDefinition Save a new immutable definition version (runs in progress keep their snapshot)
	// (PUT /agents/{handle}/definition)
	SaveAgentDefinition(ctx context.Context, request SaveAgentDefinitionRequestObject) (SaveAgentDefinitionResponseObject, error)
	// SetAgentOverride Set a project's override. An empty override removes it. Scopes can only tighten.
	// (PUT /agents/{handle}/overrides/{project})
	SetAgentOverride(ctx context.Context, request SetAgentOverrideRequestObject) (SetAgentOverrideResponseObject, error)
	// GetResolvedDefinition The definition merged with a project's override, as a run would snapshot it
	// (GET /agents/{handle}/resolved)
	GetResolvedDefinition(ctx context.Context, request GetResolvedDefinitionRequestObject) (GetResolvedDefinitionResponseObject, error)

	// (GET /agents/{handle}/runs)
	ListAgentRuns(ctx context.Context, request ListAgentRunsRequestObject) (ListAgentRunsResponseObject, error)
	// ListAgentTokens Tokens for unmanaged sessions (bring your own agent)
	// (GET /agents/{handle}/tokens)
	ListAgentTokens(ctx context.Context, request ListAgentTokensRequestObject) (ListAgentTokensResponseObject, error)
	// CreateAgentToken Mint a token. The plaintext is returned once and never stored.
	// (POST /agents/{handle}/tokens)
	CreateAgentToken(ctx context.Context, request CreateAgentTokenRequestObject) (CreateAgentTokenResponseObject, error)
	// RevokeAgentToken Revoke a token immediately
	// (DELETE /agents/{handle}/tokens/{tokenId})
	RevokeAgentToken(ctx context.Context, request RevokeAgentTokenRequestObject) (RevokeAgentTokenResponseObject, error)
	// DecideApproval Approve or deny an agent's request. The run resumes with the decision.
	// (POST /approvals/{id}/{decision})
	DecideApproval(ctx context.Context, request DecideApprovalRequestObject) (DecideApprovalResponseObject, error)
	// ListArtifacts Artifacts, newest first, with per-type counts for the tabs
	// (GET /artifacts)
	ListArtifacts(ctx context.Context, request ListArtifactsRequestObject) (ListArtifactsResponseObject, error)
	// CreateArtifact Create an artifact from markdown (body_md) or an uploaded file
	// (POST /artifacts)
	CreateArtifact(ctx context.Context, request CreateArtifactRequestObject) (CreateArtifactResponseObject, error)
	// GetArtifact An artifact with its current version, outline, readers, history and tickets
	// (GET /artifacts/{id})
	GetArtifact(ctx context.Context, request GetArtifactRequestObject) (GetArtifactResponseObject, error)
	// UpdateArtifact Edit title, summary or epic (contents change via new versions)
	// (PATCH /artifacts/{id})
	UpdateArtifact(ctx context.Context, request UpdateArtifactRequestObject) (UpdateArtifactResponseObject, error)
	// CreateArtifactVersion Add a version (markdown or file); it becomes current
	// (POST /artifacts/{id}/versions)
	CreateArtifactVersion(ctx context.Context, request CreateArtifactVersionRequestObject) (CreateArtifactVersionResponseObject, error)
	// GetArtifactContent The raw content of one version (markdown text or the stored file)
	// (GET /artifacts/{id}/versions/{versionId}/content)
	GetArtifactContent(ctx context.Context, request GetArtifactContentRequestObject) (GetArtifactContentResponseObject, error)
	// GetBootstrap Everything the shell and pickers need in one call (`me` is the local user)
	// (GET /bootstrap)
	GetBootstrap(ctx context.Context, request GetBootstrapRequestObject) (GetBootstrapResponseObject, error)
	// DeleteCriterion Remove an acceptance criterion
	// (DELETE /criteria/{id})
	DeleteCriterion(ctx context.Context, request DeleteCriterionRequestObject) (DeleteCriterionResponseObject, error)
	// UpdateCriterion Edit or tick an acceptance criterion
	// (PATCH /criteria/{id})
	UpdateCriterion(ctx context.Context, request UpdateCriterionRequestObject) (UpdateCriterionResponseObject, error)
	// GetDashboard Live Dashboard data and recorded performance statistics
	// (GET /dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)
	// ListEpicOverviews Live EpicOverviewList data and recorded performance statistics
	// (GET /epics)
	ListEpicOverviews(ctx context.Context, request ListEpicOverviewsRequestObject) (ListEpicOverviewsResponseObject, error)
	// GetHealth Liveness and dependency status
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ListInbox Attention items for the local user, including resolved history
	// (GET /inbox)
	ListInbox(ctx context.Context, request ListInboxRequestObject) (ListInboxResponseObject, error)

	// (POST /inbox/read)
	ReadInboxItem(ctx context.Context, request ReadInboxItemRequestObject) (ReadInboxItemResponseObject, error)
	// GetBacklinks Linked and unlinked mentions of an artifact, ticket, epic or agent
	// (GET /knowledge/backlinks)
	GetBacklinks(ctx context.Context, request GetBacklinksRequestObject) (GetBacklinksResponseObject, error)
	// GetGraph The local link graph around a node (1–2 hops, both directions)
	// (GET /knowledge/graph)
	GetGraph(ctx context.Context, request GetGraphRequestObject) (GetGraphResponseObject, error)
	// LinkMention Turn the first unlinked mention of a target in a source into a [[link]]
	// (POST /knowledge/link-mention)
	LinkMention(ctx context.Context, request LinkMentionRequestObject) (LinkMentionResponseObject, error)
	// ResolveLinks Resolve [[link]] texts to what they point at (for rendering)
	// (GET /knowledge/resolve)
	ResolveLinks(ctx context.Context, request ResolveLinksRequestObject) (ResolveLinksResponseObject, error)
	// SearchKnowledge Full-text search over pages, artifacts and tickets, boosted by links
	// (GET /knowledge/search)
	SearchKnowledge(ctx context.Context, request SearchKnowledgeRequestObject) (SearchKnowledgeResponseObject, error)
	// SuggestLinks [[ autocomplete over pages, artifacts, tickets, epics and agents
	// (GET /knowledge/suggest)
	SuggestLinks(ctx context.Context, request SuggestLinksRequestObject) (SuggestLinksResponseObject, error)
	// GetRunnerStatus Runner heartbeats, slots and the queue
	// (GET /runner)
	GetRunnerStatus(ctx context.Context, request GetRunnerStatusRequestObject) (GetRunnerStatusResponseObject, error)
	// GetRun A run with its turns, plan, approvals and events (the run log)
	// (GET /runs/{id})
	GetRun(ctx context.Context, request GetRunRequestObject) (GetRunResponseObject, error)
	// GetTurnLog The raw harness stream of one turn (JSONL)
	// (GET /runs/{id}/turns/{seq}/log)
	GetTurnLog(ctx context.Context, request GetTurnLogRequestObject) (GetTurnLogResponseObject, error)
	// ControlRun Pause, resume or cancel a run
	// (POST /runs/{id}/{action})
	ControlRun(ctx context.Context, request ControlRunRequestObject) (ControlRunResponseObject, error)
	// Search Search tickets, artifacts, wiki pages, epics and agents
	// (GET /search)
	Search(ctx context.Context, request SearchRequestObject) (SearchResponseObject, error)
	// ListSecrets Secret names and metadata (values are never returned)
	// (GET /secrets)
	ListSecrets(ctx context.Context, request ListSecretsRequestObject) (ListSecretsResponseObject, error)
	// SetSecret Create or replace a secret's value (409 when SECRETS_KEY isn't set)
	// (PUT /secrets)
	SetSecret(ctx context.Context, request SetSecretRequestObject) (SetSecretResponseObject, error)
	// DeleteSecret Delete a secret
	// (DELETE /secrets/{id})
	DeleteSecret(ctx context.Context, request DeleteSecretRequestObject) (DeleteSecretResponseObject, error)
	// ListTickets List tickets for a view, with optional filters
	// (GET /tickets)
	ListTickets(ctx context.Context, request ListTicketsRequestObject) (ListTicketsResponseObject, error)
	// CreateTicket Create a ticket
	// (POST /tickets)
	CreateTicket(ctx context.Context, request CreateTicketRequestObject) (CreateTicketResponseObject, error)
	// BulkUpdateTickets Apply one patch to many tickets
	// (POST /tickets/bulk)
	BulkUpdateTickets(ctx context.Context, request BulkUpdateTicketsRequestObject) (BulkUpdateTicketsResponseObject, error)
	// DispatchTickets Bulk dispatch (all or nothing)
	// (POST /tickets/dispatch)
	DispatchTickets(ctx context.Context, request DispatchTicketsRequestObject) (DispatchTicketsResponseObject, error)
	// GetTicket A ticket with its criteria
	// (GET /tickets/{key})
	GetTicket(ctx context.Context, request GetTicketRequestObject) (GetTicketResponseObject, error)
	// UpdateTicket Change ticket fields. Omitted fields are untouched; null clears.
	// (PATCH /tickets/{key})
	UpdateTicket(ctx context.Context, request UpdateTicketRequestObject) (UpdateTicketResponseObject, error)
	// ListTicketActivity The ticket timeline, oldest first
	// (GET /tickets/{key}/activity)
	ListTicketActivity(ctx context.Context, request ListTicketActivityRequestObject) (ListTicketActivityResponseObject, error)
	// AttachArtifact Attach an artifact to a ticket as context (or as generated output)
	// (POST /tickets/{key}/artifacts)
	AttachArtifact(ctx context.Context, request AttachArtifactRequestObject) (AttachArtifactResponseObject, error)
	// DetachArtifact Remove an artifact from a ticket
	// (DELETE /tickets/{key}/artifacts/{artifactId})
	DetachArtifact(ctx context.Context, request DetachArtifactRequestObject) (DetachArtifactResponseObject, error)
	// CreateComment Comment on a ticket (appears in the timeline)
	// (POST /tickets/{key}/comments)
	CreateComment(ctx context.Context, request CreateCommentRequestObject) (CreateCommentResponseObject, error)
	// CreateCriterion Add an acceptance criterion
	// (POST /tickets/{key}/criteria)
	CreateCriterion(ctx context.Context, request CreateCriterionRequestObject) (CreateCriterionResponseObject, error)
	// GetDispatchPreview Exactly what a run of this ticket would get, for the dispatch dialog
	// (GET /tickets/{key}/dispatch)
	GetDispatchPreview(ctx context.Context, request GetDispatchPreviewRequestObject) (GetDispatchPreviewResponseObject, error)
	// DispatchTicket Approve & dispatch: queue a managed run for the assigned agent
	// (POST /tickets/{key}/dispatch)
	DispatchTicket(ctx context.Context, request DispatchTicketRequestObject) (DispatchTicketResponseObject, error)
	// ExportWiki Every page as an Obsidian-compatible vault (zip of markdown files)
	// (GET /wiki/export)
	ExportWiki(ctx context.Context, request ExportWikiRequestObject) (ExportWikiResponseObject, error)
	// ImportWiki Import a vault zip; each .md file creates or replaces the page at its path
	// (POST /wiki/import)
	ImportWiki(ctx context.Context, request ImportWikiRequestObject) (ImportWikiResponseObject, error)
	// GetWikiPage A page by path (or a renamed page's old path)
	// (GET /wiki/page)
	GetWikiPage(ctx context.Context, request GetWikiPageRequestObject) (GetWikiPageResponseObject, error)
	// ListWikiPages Every wiki page (the page tree), with pending suggestion counts
	// (GET /wiki/pages)
	ListWikiPages(ctx context.Context, request ListWikiPagesRequestObject) (ListWikiPagesResponseObject, error)
	// CreateWikiPage Create a page at a path
	// (POST /wiki/pages)
	CreateWikiPage(ctx context.Context, request CreateWikiPageRequestObject) (CreateWikiPageResponseObject, error)
	// SaveWikiPage Save a page's body (a new version, silently) and/or move it to a new path
	// (PUT /wiki/pages/{id})
	SaveWikiPage(ctx context.Context, request SaveWikiPageRequestObject) (SaveWikiPageResponseObject, error)
	// ListWikiSuggestions Agent edits waiting for a person, oldest first
	// (GET /wiki/suggestions)
	ListWikiSuggestions(ctx context.Context, request ListWikiSuggestionsRequestObject) (ListWikiSuggestionsResponseObject, error)
	// DecideWikiSuggestion Accept (publish as the next version) or reject a suggestion
	// (POST /wiki/suggestions/{versionId}/{decision})
	DecideWikiSuggestion(ctx context.Context, request DecideWikiSuggestionRequestObject) (DecideWikiSuggestionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

